/**
 * What the crawler feeds the app: barcodes, typed names and prices, drawn from lists.
 * The lists are the whole of its "creativity": nothing here is generated by a model.
 */

/** The check digit of a GTIN body (every digit but the last). Works for any length. */
export function gtinCheckDigit(body) {
  let sum = 0;
  const digits = String(body).split('').reverse();
  for (let i = 0; i < digits.length; i += 1) sum += Number(digits[i]) * (i % 2 === 0 ? 3 : 1);
  return (10 - (sum % 10)) % 10;
}

/** A well-formed GTIN-13 from a 12-digit body. */
export const gtin13 = (body12) => `${body12}${gtinCheckDigit(body12)}`;

/** The two products the route table knows (harness KD plus one more), so a "valid known" code gets a real answer. */
export const KNOWN_CODES = ['0068100084245', gtin13('006810008425')];
/** Well-formed codes the route table has never heard of. */
export const UNKNOWN_CODES = [gtin13('062639000011'), gtin13('055555555555'), gtin13('012345678905')];
/** Not a barcode: wrong length, bad check digit, letters, spaces. The screen must refuse these without falling over. */
export const MALFORMED_CODES = ['12345', '0068100084240', 'abcdefghijklm', '00681 00084245', '9'.repeat(30), '0'];

/** The ordered list of barcode inputs, each tagged with what the route table will say about it. */
export const BARCODES = [
  ...KNOWN_CODES.map((code) => ({ code, kind: 'known' })),
  ...UNKNOWN_CODES.map((code) => ({ code, kind: 'unknown' })),
  ...MALFORMED_CODES.map((code) => ({ code, kind: 'malformed' })),
];

/** Typed names: real, typo'd, emoji, very long, empty, and a few awkward strings. */
export const NAMES = [
  'Kraft Dinner', 'kraft', 'Kraf Dinnr', 'milk 2%', 'Lactancia', 'president choice', 'Cheerios',
  'Ça va', 'crème fraîche', '🍎 apples', '🧀🧀🧀', 'a', '  ', '', 'x'.repeat(200), 'Kraft Dinner '.repeat(16),
  '<b>bold</b>', "O'Brien's", '100%', 'a&b', '../../etc', '${x}', '\\n', 'Loblaws', 'No Frills',
];

/** Typed prices, as the field would be handed them. */
export const PRICES = ['0', '0.01', '6.99', '99999', '-1', 'abc', '1,99', '4.99', '12', '0.00', ' ', '1e3'];

/** Pad key sequences for a price: digits and the point, because that is all the pad can send. */
export const PAD_PRICES = ['0', '001', '699', '99999999', '499', '5', '1', '12345', '0000'];

/** Short texts for a number field (percent off, items in a deal). */
export const NUMBERS = ['0', '1', '2', '3', '10', '25', '50', '99', '100', '101', '-5', '1.5', ''];
